"use client";
import { useId, useRef, useState } from "react";
import "./otp-input.css";

/** One real input drawn as separate cells, so paste, SMS autofill, and screen readers just work. */
export function OtpInput({
  length = 6,
  label = "Verification code",
  onComplete,
  numeric = true,
  className = "",
}: {
  length?: number;
  label?: string;
  onComplete?: (code: string) => void;
  numeric?: boolean;
  className?: string;
}) {
  const id = useId();
  const input = useRef<HTMLInputElement>(null);
  const [value, setValue] = useState("");
  const [focused, setFocused] = useState(false);
  const [caret, setCaret] = useState(0);
  const sync = () => setCaret(Math.min(input.current?.selectionStart ?? value.length, length - 1));
  return (
    <div className={`forme-otp ${className}`} style={{ ["--forme-otp-length" as string]: length }}>
      <label htmlFor={id} className="forme-otp-label">
        {label}
      </label>
      <div className="forme-otp-cells">
        <input
          ref={input}
          id={id}
          value={value}
          inputMode={numeric ? "numeric" : "text"}
          autoComplete="one-time-code"
          pattern={numeric ? `\\d{${length}}` : undefined}
          spellCheck={false}
          onFocus={() => (setFocused(true), sync())}
          onBlur={() => setFocused(false)}
          onSelect={sync}
          onChange={(e) => {
            const next = (numeric ? e.target.value.replace(/\D/g, "") : e.target.value.replace(/\s/g, "")).slice(0, length);
            setValue(next);
            setCaret(Math.min(next.length, length - 1));
            if (next.length === length) onComplete?.(next);
          }}
        />
        {Array.from({ length }, (_, i) => (
          <span
            key={i}
            aria-hidden="true"
            className="forme-otp-cell"
            data-filled={i < value.length || undefined}
            data-active={(focused && i === Math.min(caret, value.length)) || undefined}
          >
            {value[i] ?? ""}
          </span>
        ))}
      </div>
    </div>
  );
}

.forme-otp-label {
  display: block;
  margin-bottom: 10px;
  font-size: 14px;
  opacity: 0.7;
}
.forme-otp-cells {
  position: relative;
  display: grid;
  grid-template-columns: repeat(var(--forme-otp-length), 48px);
  gap: 8px;
}
/* The real input covers the cells invisibly and receives every keystroke and paste. */
.forme-otp-cells input {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: transparent;
  caret-color: transparent;
  font-size: 16px;
  letter-spacing: 48px;
  cursor: text;
}
.forme-otp-cell {
  display: grid;
  place-items: center;
  height: 56px;
  border-radius: 12px;
  background: color-mix(in srgb, currentColor 5%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 16%, transparent);
  font-size: 22px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  transition:
    box-shadow 0.18s,
    transform 0.18s;
}
.forme-otp-cell[data-filled] {
  animation: forme-otp-pop 0.22s cubic-bezier(0.3, 1.4, 0.5, 1);
}
.forme-otp-cell[data-active] {
  box-shadow:
    inset 0 0 0 1.5px currentColor,
    0 0 0 4px color-mix(in srgb, currentColor 12%, transparent);
}
.forme-otp-cell[data-active]:empty::after {
  content: "";
  width: 2px;
  height: 22px;
  background: currentColor;
  animation: forme-otp-caret 1s steps(1) infinite;
}
@keyframes forme-otp-pop {
  from {
    transform: scale(0.85);
  }
}
@keyframes forme-otp-caret {
  50% {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .forme-otp-cell,
  .forme-otp-cell[data-filled],
  .forme-otp-cell[data-active]:empty::after {
    transition: none;
    animation: none;
  }
}
